// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{})
}

type ChiServerOptions struct {
	BaseURL          string
	BaseRouter       chi.Router
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, r chi.Router) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseRouter: r,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, r chi.Router, baseURL string) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseURL:    baseURL,
		BaseRouter: r,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options ChiServerOptions) http.Handler {
	r := options.BaseRouter

	if r == nil {
		r = chi.NewRouter()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/admin/audit_logs", wrapper.ListAdminAuditLogs)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/admin/auth/sessions", wrapper.ListAdminAuthSessions)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/v1/admin/auth/sessions/{id}/revoke", wrapper.RevokeAdminAuthSession)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/v1/auth/device_codes", wrapper.CreateDeviceCode)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/v1/auth/device_codes/{user_code}/approve", wrapper.ApproveDeviceCode)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/v1/auth/device_codes/{user_code}/deny", wrapper.DenyDeviceCode)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/v1/auth/logout", wrapper.LogoutSession)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/v1/auth/tokens", wrapper.ExchangeDeviceCode)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/v1/auth/tokens/refresh", wrapper.RefreshAccessToken)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/dashboard", wrapper.GetDashboard)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/networks/devices", wrapper.ListNetworkDevices)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/v1/networks/devices", wrapper.CreateNetworkDevice)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/api/v1/networks/devices/{id}", wrapper.DeleteNetworkDevice)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/networks/devices/{id}", wrapper.GetNetworkDevice)
	})
	r.Group(func(r chi.Router) {
		r.Patch(options.BaseURL+"/api/v1/networks/devices/{id}", wrapper.PatchNetworkDevice)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/networks/vlans", wrapper.ListVlans)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/v1/networks/vlans", wrapper.CreateVlan)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/api/v1/networks/vlans/{id}", wrapper.DeleteVlan)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/networks/vlans/{id}", wrapper.GetVlan)
	})
	r.Group(func(r chi.Router) {
		r.Patch(options.BaseURL+"/api/v1/networks/vlans/{id}", wrapper.PatchVlan)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/profile", wrapper.GetProfile)
	})
	r.Group(func(r chi.Router) {
		r.Patch(options.BaseURL+"/api/v1/profile/preferences", wrapper.PatchProfilePreferences)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/profile/sessions", wrapper.ListProfileSessions)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/v1/profile/sessions/revoke_others", wrapper.RevokeOtherProfileSessions)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/v1/profile/sessions/{id}/revoke", wrapper.RevokeProfileSession)
	})

	return r
}

